import yaml
import json

with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_8/projects/acr-vla-conformal-refinement/registry.yaml', 'r') as f:
    registry = yaml.safe_load(f)

# Find Spatial seed experiments
spatial_exps = {}
for exp_id, exp_data in registry.items():
    if 'spatial' in exp_id.lower() and any(f's4{i}' in exp_id or f'seed4{i}' in exp_id for i in range(2, 10)):
        spatial_exps[exp_id] = exp_data

# Extract VLA-only and Adaptive data
vla_only = {}
adaptive = {}

for exp_id in sorted(spatial_exps.keys()):
    exp = spatial_exps[exp_id]
    if 'vla_only' in exp_id or 'vla-only' in exp_id:
        # Extract seed number
        for seed in range(42, 50):
            if f's{seed}' in exp_id or f'seed{seed}' in exp_id:
                notes = exp.get('notes', '')
                pct = exp.get('metrics', {}).get('percentage', None)
                if not pct and notes:
                    # Try to parse from notes
                    import re
                    match = re.search(r'(\d+(?:\.\d+)?)%', notes)
                    if match:
                        pct = float(match.group(1))
                vla_only[seed] = {'exp_id': exp_id, 'percentage': pct, 'notes': notes[:200]}
                break
    elif 'adaptive' in exp_id.lower() and 'spatial' in exp_id:
        for seed in range(42, 50):
            if f's{seed}' in exp_id or f'seed{seed}' in exp_id:
                notes = exp.get('notes', '')
                pct = exp.get('metrics', {}).get('percentage', None)
                if not pct and notes:
                    import re
                    match = re.search(r'(\d+(?:\.\d+)?)%', notes)
                    if match:
                        pct = float(match.group(1))
                adaptive[seed] = {'exp_id': exp_id, 'percentage': pct, 'notes': notes[:200]}
                break

print("VLA-only Spatial Results:")
for seed in sorted(vla_only.keys()):
    print(f"  s{seed}: {vla_only[seed]}")

print("\nAdaptive Spatial Results:")
for seed in sorted(adaptive.keys()):
    print(f"  s{seed}: {adaptive[seed]}")
EOF
